import re
import six
import logging
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class Filter(object):
    def __init__(self, reader, throughput_data_factory):
        self._reader = reader
        self._throughput_data_factory = throughput_data_factory

    @property
    def reader(self):
        return self._reader

    @property
    def identifiers(self):
        return []

    @abstractmethod
    def _extract(self, content):
        pass  # return (device_id, value)

    def do(self):
        with self.reader as read:
            for log_entry in read.log_entries:
                data = self._filter(log_entry)
                if data:
                    yield data

    def _filter(self, log_entry):
        raw_string = str(log_entry.syslog_msg['raw_string'])
        for identifier in self.identifiers:
            if identifier not in raw_string:
                break
        else:
            data = self._extract(raw_string)
            if not data:
                return None
            return self._throughput_data_factory.create(device_id=data[0],
                                                       throughput_value=data[1],
                                                       timestamp=log_entry.timestamp)

    def on_filter(self, log_entry):
        return self._filter(log_entry)


class UplinkOnCellFilter(Filter):
    def __init__(self, reader, throughput_data_factory):
        super(UplinkOnCellFilter, self).__init__(reader, throughput_data_factory)

    @property
    def identifiers(self):
        return ['UlCounterUpdate', 'rlcPduBytes']

    def _extract(self, content):
        results = re.findall(r"(\d+)\srlcPduBytes.*nrCellIdentity\s(\d+)", content)
        if not results:
            logging.warning("omit an incomplete line which has 'UlCounterUpdate' but has not rlcPduBytes or "
                            "nrCellIdentity: {}".format(content))
            return None
        tput_str, cell_id = results[0]
        return cell_id, int(tput_str)


class DownlinkOnCellFilter(Filter):
    def __init__(self, reader, throughput_data_factory):
        super(DownlinkOnCellFilter, self).__init__(reader, throughput_data_factory)

    @property
    def identifiers(self):
        return ['SentDataMeasurementCounting', 'DataPdu']

    def _extract(self, content):
        results = re.findall(r"nrCellId\s(\d+).*\[(.*DataPdu.*?)]", content)
        if not results:
            logging.warning("omit an incomplete line which has 'UlCounterUpdate' but "
                            "has not completed information about nrCellId or DataPdu: {}".format(content))
            return None
        cell_id, pdu_str = results[0]  # like ('1250', 'TBS|MacCe|StatusPdu|DataPdu: 2752335|0|240|2657265')
        keys_str, values_str = pdu_str.split(':')
        keys = keys_str.strip().split('|')
        values = values_str.strip().split('|')
        data_pdu = dict(zip(keys, values))['DataPdu']

        return cell_id, int(data_pdu)
